using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class FinishLighting {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B4_Finish/";const string A="Assets/Afrer_Seconds/05.Model/Environment/B4/";
 static Scene Check(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B4_Circular.unity"))throw new Exception("Saved B4 edit required");return s;}
 public static object Run(){var s=Check();var rows=new List<object>();foreach(var p in JArray.Parse(File.ReadAllText(H+"lights_before.json"))){GlobalObjectId.TryParse((string)p["id"],out var gid);var l=GlobalObjectId.GlobalObjectIdentifierToObjectSlow(gid) as Light;if(!l)throw new Exception("Light missing");string n=l.transform.parent.name;int index=0;int.TryParse(n.Split('_').Last(),out index);bool ceiling=n.Contains("CeilingLight"),sealedLight=n.Contains("SealedTaskLight");l.shadows=(ceiling||sealedLight)&&index%2==0?LightShadows.None:LightShadows.Soft;l.intensity=(float)p["intensity"]*(ceiling?.96f:1f);l.color=ceiling?new Color(.94f,.965f,1):new Color(.965f,.98f,1);l.shadowStrength=.90f;l.shadowResolution=UnityEngine.Rendering.LightShadowResolution.Medium;PrefabUtility.RecordPrefabInstancePropertyModifications(l);rows.Add(new{id=(string)p["id"],parent=n,l.intensity,l.range,color=l.color.ToString(),shadows=l.shadows.ToString()});}
 RenderSettings.ambientSkyColor=new Color(.34f,.35f,.37f);RenderSettings.ambientEquatorColor=new Color(.245f,.255f,.275f);RenderSettings.ambientGroundColor=new Color(.17f,.18f,.20f);RenderSettings.reflectionIntensity=.65f;
 var names=new[]{"B4O_Coat","B4O_Steel","B4O_Dark","B4O_Rubber","LB_Coat","LB_Steel"};var map=new Dictionary<Material,Material>();int changed=0;foreach(var r in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true))){var ms=r.sharedMaterials;bool edit=false;for(int i=0;i<ms.Length;i++){var old=ms[i];if(!old||!names.Contains(old.name))continue;if(!map.TryGetValue(old,out var m)){string path=A+"Materials/FL_"+old.name+".mat";m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(old){name="FL_"+old.name};AssetDatabase.CreateAsset(m,path);}bool steel=old.name.EndsWith("Steel"),coat=old.name.EndsWith("Coat");m.SetFloat("_Smoothness",steel?.36f:coat?.28f:.25f);if(steel)m.SetColor("_BaseColor",new Color(.42f,.44f,.45f));m.enableInstancing=true;EditorUtility.SetDirty(m);map[old]=m;}ms[i]=m;edit=true;}if(edit){r.sharedMaterials=ms;PrefabUtility.RecordPrefabInstancePropertyModifications(r);changed++;}}
 EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);AssetDatabase.SaveAssets();File.WriteAllText(H+"lights_after.json",JsonConvert.SerializeObject(rows,Formatting.Indented));return new{lights=rows.Count,shadowLights=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Light>()).Count(l=>l.shadows!=LightShadows.None),materialCopies=map.Count,renderers=changed};}
 public static object Reflections(){var s=Check();var parent=GameObject.Find("B4_FinishReflections");if(!parent)parent=new GameObject("B4_FinishReflections");var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));bool was=player.activeSelf;player.SetActive(false);int count=0;try{foreach(var r in JObject.Parse(File.ReadAllText(R+"/SourceAssets/B4_LayoutPolish/layout.json"))["rooms"]){string id=(string)r["id"];var tr=parent.transform.Find("Reflection_"+id);var g=tr?tr.gameObject:new GameObject("Reflection_"+id);g.transform.SetParent(parent.transform,false);g.transform.position=new Vector3((float)r["x"],-64,-(float)r["v"]);var p=g.GetComponent<ReflectionProbe>();if(!p)p=g.AddComponent<ReflectionProbe>();float rad=(float)r["r"];p.size=new Vector3(rad*2,rad+2,rad*2);p.center=new Vector3(0,rad*.5f-2,0);p.blendDistance=1;p.resolution=128;p.hdr=true;p.boxProjection=true;p.mode=ReflectionProbeMode.Custom;p.renderDynamicObjects=true;p.clearFlags=ReflectionProbeClearFlags.SolidColor;p.backgroundColor=new Color(.035f,.04f,.05f);p.intensity=.75f;string file=A+"Textures/FL_Reflection_"+id+".exr";if(!Lightmapping.BakeReflectionProbe(p,file))throw new Exception("Probe failed: "+id);AssetDatabase.ImportAsset(file,ImportAssetOptions.ForceSynchronousImport);p.customBakedTexture=AssetDatabase.LoadAssetAtPath<Cubemap>(file);if(!p.customBakedTexture)throw new Exception("No cube");count++;}}finally{player.SetActive(was);}EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);AssetDatabase.SaveAssets();return new{baked=count};}
}
